(1, 'Weekly Top 10 All TV Channel', '2', 'N', '', '[{"no":"1","id":"14","title":"Kompas TV","slug":"kompas-tv","description":"Kompas TV menghadirkan program berita terkini seputar nasional, internasional, politik, ekonomi, olahraga, entertainment dan berita eksklusif.(www.kompas.tv)","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1527239100_square.png","image_landscape":"","image_potrait":"","category":"1"},{"no":"2","id":"7","title":"tvOne","slug":"tvone","description":"tvOne menghadirkan program berita yang mencakup politik dan update terkini, serta program olahraga dan hiburan. (www.tvonenews.tv)","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/TV_One_1.png","image_landscape":"","image_potrait":"","category":"1"},{"no":"3","id":"117","title":"DensFood Channel","slug":"densfood-channel","description":"DensFood Channel merupakan in-house Dens.TV yang menghadirkan konten menginspirasi seputar kuliner dan memasak.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/Dens_Food_Channel_(Trial)_1.jpg","image_landscape":"","image_potrait":"","category":"1"},{"no":"4","id":"100","title":"K-PLUS HD","slug":"k-plus-hd","description":"K-PLUS menayangkan hiburan Korea terbaik yang menampilkan serial drama dan program-program yang bervariasi yang dimana beberapa serial dramanya ditayangkan dalam waktu 24 jam dari Korea. (www.kplus-asia.com\\/)","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/K-PLUS_(Trial)_1.jpg","image_landscape":"","image_potrait":"","category":"2"},{"no":"5","id":"6","title":"Metro TV","slug":"metro-tv","description":"METRO TV menghadirkan program berita terkini seputar politik, ekonomi, dan informasi yang beragam. (www.metrotvnews.com)","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/Metro_TV_1.png","image_landscape":"","image_potrait":"","category":"1"},{"no":"6","id":"8","title":"antv","slug":"antv","description":"ANTV menghadirkan program