(2, 'Channel Premium Pilihan', '2', 'N', '5', '[{"no":"1","id":"92","title":"My Cinema Europe HD","slug":"my-cinema-europe-hd","description":"My Cinema Europe didedikasikan untuk film-film terbaik dari dunia film Eropa yang merupakan rilis baru, hit box-office, pemenang penghargaan dan klasik.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/My_Cinema_Europe_HD_1.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"2","id":"98","title":"Motorvision+","slug":"motorvision","description":"Motorvision+ menghadirkan siaran langsung motorsport secara eksklusif, dokumenter, test drive dinamis dan beragam konten premium.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/Motorvision+_new logo183x174@3x.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"3","id":"128","title":"Stingray Classica","slug":"stingray-classica","description":"Stingray Classica merupakan channel yang didedikasikan untuk musik klasik, konser, opera, balet, dan dokumenter.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1701423589_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"4","id":"130","title":"Dance TV","slug":"dance-tv","description":"Dance TV menghadirkan musik elektronik, masing-masing difokuskan pada genre tertentu sehingga selalu dapat mendengar suara yang sesuai dengan selera dan suasana hati saat ini.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1701423510_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"5","id":"143","title":"Qwest TV","slug":"qwest-tv","description":"Qwest TV adalah layanan streaming milik Quincy Jones yang menghadirkan dokumenter, konser, dan wawancara seputar musik dari Bebop hingga Hip Hop.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1763699064_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"6","id":"127","title":"Crema TV","slug":"crema-tv","description":"Crema TV menghadirkan channel lifestyle tentang dunia kopi.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1701422013_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""}]', 'Y', '2023-10-27 15:07:16', '2026-09-18 03:08:29', '/top/section/update_section'),
(3, 'Weekly Top 10 TV Show', '7', 'Y', '', '[{"no":"1","id":"22","title":"Findland Papa Episode 2","slug":"findland-papa-episode-2","description":"Yuri melihat poster dengan iklan pekerjaan mencari \\"anggota keluarga\\" untuk bekerja di sebuah kafe bernama Finland Papa. Bosan makan makanan yang dibeli di toko, dia pergi ke kafe dan diundang makan malam bersama staf.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/finland papa_@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699954723_top_tvshowpotrait_v1.jpg"},{"no":"2","id":"26","title":"Tears of the Sun","slug":"tears-of-the-sun","description":"Seorang komandan operasi khusus, bersama pasukannya, berangkat untuk menyelamatkan Dr Lena dari hutan Nigeria. Namun, Dr Lena setuju untuk bergabung dengan mereka hanya jika mereka setuju untuk menyelamatkan 70 pengungsi lainnya juga.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/tears of the sun_@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699954782_top_tvshowpotrait_v1.jpg"},{"no":"3","id":"23","title":"Everything Under Control","slug":"everything-under-control","description":"Ketika dua penjaga keamanan melakukan perjalanan ke desa terpencil untuk mengambil beberapa perhiasan curian, mereka bertemu dengan penduduk desa yang penuh semangat dan hantu misterius.\\n","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/Everything Under Control@3x (1).jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699954918_top_tvshowpotrait_v1.jpg"},{"no":"4","id":"28","title":"Final Shot","slug":"final-shot","description":"Veteran alkoholik yang dipermalukan harus membangkitkan kembali semua keterampilan mematikannya, dan melacak mantan majikannya ketika dia gagal menyelesaikan serangan terakhirnya.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/final shot@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955000_top_tvshowpotrait_v1.jpg"},{"no":"5","id":"25","title":"The Trigonal: Fight for Justice","slug":"the-trigonal-fight-for-justice","description":"Ketika orang-orang jahat menyerang istrinya dan membunuh seorang teman dekatnya, seorang mantan juara seni bela diri campuran bangkit melawan mereka untuk membalas dendam.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/The Trigonal_ Fight for Justice@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955096_top_tvshowpotrait_v1.jpg"},{"no":"6","id":"27","title":"The Beaver","slug":"the-beaver","description":"Walter, seorang eksekutif yang depresi, mencapai titik terendah ketika istrinya mengusirnya dari rumah. Pada titik terendahnya, ia mulai menggunakan boneka tangan berang-berang untuk berkomunikasi dengan orang-orang dan mengatasi masalahnya.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/The Beaver@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955214_top_tvshowpotrait_v1.jpg"},{"no":"7","id":"24","title":" Bonanza S2 E21 - Vengeance","slug":"bonanza-s2-e21-vengeance","description":"Hoss menyalahkan dirinya sendiri atas kematian tetangga yang ia pukul demi membela diri -- begitu pula saudara laki-laki pria tersebut.","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/Bonanza S2 E21 - Vengeance@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955320_top_tvshowpotrait_v1.jpg"},{"no":"8","id":"29","title":"Chicken Run","slug":"chicken-run","description":"\\nSeekor ayam jago Amerika jatuh cinta pada ayam betina di peternakan ayam Inggris. Mereka ingin melarikan diri. Namun pemilik peternakan yang licik ingin mengendalikan mereka dan mengubahnya menjadi pai ayam.\\n","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/Chicken Run@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955437_top_tvshowpotrait_v1.jpg"},{"no":"9","id":"30","title":"The Tea House","slug":"the-tea-house","description":"Kakak Cheng adalah pemilik restoran tercinta yang baik hati. Ketika sekelompok gangster yang kejam mulai meneror lingkungannya, dia harus turun tangan untuk melindungi keluarganya dan penduduk desa.\\n","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/The Tea House@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955493_top_tvshowpotrait_v1.jpg"},{"no":"10","id":"31","title":"After-School Hanako-kun","slug":"after-school-hanako-kun","description":"MEMBUKA! TEMUKAN APA YANG DILAKUKAN MISTERI SEKOLAH SETELAH SEKOLAH!?Hanako-kun yang si hantu dan asisten fananya, Nene Yashiro, biasanya sibuk menyelesaikan berbagai insiden supernatural di Akademi Kamome, tapi bagaimana mereka menghabiskan waktu saat istirahat dari sekolah? semua itu? ...","type":"catchup_schedule","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowbanner_v1\\/1280x720\\/After-School Hanako-kun@3x.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/top_tvshowpotrait_v1\\/575x1028\\/1699955602_top_tvshowpotrait_v1.jpg"}]', 'N', '2023-10-27 15:54:49', '2023-11-22 06:48:33', '/top/section/inactivated_section'),
(4, 'Tayangan Pilihan Minggu Ini', '6', 'N', '', '[{"no":"1","id":"154","title":"Loving Every Minute Promo Video","slug":"loving-every-minute-promo-video","description":"Senin, 27 Oktober, jam 18:00 WIB | Ketika Stephanie mewarisi sebuah jam tangan, ia mengetahui bahwa jam itu memungkinkannya untuk kembali ke masa lalu selama lima menit, sekali dalam sehari. Namun, semakin sering ia menggunakannya, kehidupannya\\u2014termasuk kisah asmaranya dengan rekan kerjanya, Hunter\\u2014tidak berjalan seperti yang ia harapkan.","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551142_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551085_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01386\\/index5.m3u8"},{"no":"3","id":"155","title":"Classical Halloween Promo Video","slug":"classical-halloween-promo-video","description":"1 November, Sabtu, Jam 5:27 WIB | Stingray Classica turut merayakan perayaan tahunan Halloween. Nikmati rangkaian karya musik yang menghantui jiwa, seperti \\u201cDies Irae\\u201d yang megah dari Requiem karya Giuseppe Verdi; \\u201cSonge d\\u2019une nuit de Sabbat\\u201d (Mimpi di Malam Sabat) dengan suasana mencekam dari Symphonie fantastique karya Hector Berlioz; serta Funeral March yang ikonis dari Piano Sonata No. 2 karya Fr\\u00e9d\\u00e9ric Chopin, yang telah dimainkan di pemakaman di seluruh dunia\\u2014termasuk pada pemakaman Chopin sendiri.","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551135_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551078_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01381\\/index5.m3u8"},{"no":"4","id":"151","title":"Limbo PREMIERE  Prromo Video","slug":"limbo-premiere-prromo-video","description":"PREMIERE, 1 November, Sabtu, Jam 20:00 WIB | Film satu pengambilan tanpa potongan. Ketika Ana, seorang manajer kepatuhan muda, menemukan tagihan yang tidak biasa tinggi dalam laporan keuangan perusahaannya, ia sama sekali tidak menyadari gelombang kejut seperti apa yang akan ditimbulkan oleh penyelidikannya...","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551140_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551083_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01382\\/index5.m3u8"},{"no":"5","id":"185","title":"The London Symphony Orchestra (LSO) presents Tchaikovsky Promo Video","slug":"the-london-symphony-orchestra-lso-presents-tchaikovsky-promo-video","description":"Dari 2 November, setiap Minggu, dari Jam 04:00 WIB | Pada bulan November, Stingray Classica menayangkan perdana empat pertunjukan mengesankan dari London Symphony Orchestra (LSO) setiap hari Minggu pukul 04.00 pagi. Kali ini, LSO menampilkan mahakarya-mahakarya dari Pyotr Ilyich Tchaikovsky.","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551147_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551115_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01384\\/index5.m3u8"},{"no":"6","id":"153","title":"STAR STUNT: KIM MOO-YUL Promo Video","slug":"star-stunt-kim-moo-yul-promo-video","description":"Dari 2 November, setiap Minggu, 21:00 WIB | STAR STUNT: KIM MOO-YUL","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551146_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551099_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01383\\/index5.m3u8"},{"no":"7","id":"187","title":"Universal Soldier PREMIERE Promo Video","slug":"universal-soldier-premiere-promo-video","description":"PREMIERE, 26 Oktober, Minggu, 19:55 WIB | Dua tentara yang tewas di Vietnam dihidupkan kembali bertahun-tahun kemudian sebagai prajurit super berwujud cyborg. Namun, ketika ingatan masa lalu mereka muncul kembali, mereka melarikan diri\\u2014menyulut pertarungan brutal antara mantan rekan seperjuangan","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1760943538_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1760943483_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01378\\/index5.m3u8"},{"no":"8","id":"186","title":"Italian Opera Season Promo Video","slug":"italian-opera-season-promo-video","description":"Dari 2 November, setiap Minggu, dari Jam 21:00 WIB | Italia akan selalu menjadi tempat kelahiran opera! Setiap bulan November, gedung-gedung opera di seluruh negeri menyambut dimulainya musim opera yang baru. Setiap hari Minggu, Stingray Classica menyiarkan mahakarya dari para komponis terbaik Italia untuk merayakan pembukaan musim opera tahun ini, termasuk Madama Butterfly karya Giacomo Puccini, La forza del destino karya Giuseppe Verdi, Lucia di Lammermoor karya Gaetano Donizetti, Il barbiere di Siviglia karya Gioachino Rossini, dan I puritani karya Vincenzo Bellini.","type":"trailer","image_square":"","image_landscape":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_landscape_v1\\/1280x720\\/1761551138_upcoming_landscape_v1.jpg","image_potrait":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/upcoming_potrait_v1\\/575x1028\\/1761551080_upcoming_potrait_v1.jpg","trailer_url":"https:\\/\\/op-svod.dens.tv\\/04\\/MVUPC01385\\/index5.m3u8"}]', 'N', '2023-10-31 15:38:17', '2025-11-03 03:00:04', '/top/section/inactivated_section'),
