(8, 'Life&Style', '5', 'N', '', '[{"no":"1","id":"1812","title":"Wayang, Kesenian Yang Harus Tetap Dilestarikan!","slug":"wayang-kesenian-yang-harus-tetap-dilestarikan","description":"Wayang menjadi salah satu warisan budaya Indonesia sebagai aset budaya nasional.","type":"article","image_square":"","image_landscape":"http:\\/\\/op-picture.dens.tv\\/wp\\/img\\/denslife_v1\\/1280x720\\/1699255131_denslife_v1.jpg","image_potrait":"","id_content_category":"246","title_content_category":"DLS-DensLife&Style"},{"no":"2","id":"1802","title":"Kreasi Camilan Halloween Bersama Anak: Lolipop Kue Labu","slug":"kreasi-camilan-halloween-bersama-anak-lolipop-kue-labu","description":"Ajak anak-anak untuk mengkreasikan camilan dengan membuat lolipop kue labu di hari Halloween. Caranya sangat mudah dan bahan-bahannya gampang ditemui di rumah.","type":"article","image_square":"","image_landscape":"http:\\/\\/op-picture.dens.tv\\/wp\\/img\\/denslife_v1\\/1280x720\\/1698645304_denslife_v1.jpg","image_potrait":"","id_content_category":"246","title_content_category":"DLS-DensLife&Style"},{"no":"3","id":"1801","title":"Rasakan Sensasi Makan Jari Penyihir Menyeramkan Tapi Lezat","slug":"rasakan-sensasi-makan-jari-penyihir-menyeramkan-tapi-lezat","description":"Coba rasakan sensasi makan jari penyihir yang terbuat dari puff pastry dengan isian sosis yang lezat dicampur pasta tomat dan kukunya yang terbuat dari kacang almond.","type":"article","image_square":"","image_landscape":"http:\\/\\/op-picture.dens.tv\\/wp\\/img\\/denslife_v1\\/1280x720\\/1698047079_denslife_v1.jpg","image_potrait":"","id_content_category":"246","title_content_category":"DLS-DensLife&Style"},{"no":"4","id":"1800","title":"6 Ide Kostum Halloween Terinspirasi Dari Film Dan Series","slug":"6-ide-kostum-halloween-terinspirasi-dari-film-dan-series","description":"Buat kamu yang belum punya ide kostum Halloween untuk tanggal 31 Oktober nanti, berikut enam ide kostum halloween dari karakter film dan series favoritmu!","type"