(11, 'Free VoD ', '1', 'Y', '', '[{"no":"1","id":"7648","title":"A River Within | Rated : P-13","slug":"a-river-within-rated-p-13","description":"Content Rights: CinemaWorld.\\nSinopsis: \\"A River Within\\" adalah sebuah film drama aksi Afrika Selatan tahun 2018 yang disutradarai oleh Ivan Botha. Lima wanita dengan masalah pribadi masing-masing melakukan perjalanan ke Sungai Orange untuk menjalani \\"Terapi Petualangan\\" mereka. Ketika sesuatu yang tidak diinginkan terjadi dalam petualangan arung jeram mereka di sungai, naluri bertahan hidup mereka teruji dan mereka harus mencari kekuatan dari dalam diri mereka.","type":"vod","image_square":"","image_landscape":"http://pic.dens.tv/poster/files/lands/A-RIVER-WITHIN-LANDSCAPE1280x720@3x.jpg","image_potrait":"http://pic.dens.tv/poster/files/port/A-RIVER-WITHIN549x825@3x.jpg"},{"no":"2","id":"4960","title":"UTWT 2021 Ep1","slug":"utwt-2021-ep1","description":"Konten ini milik HorizonSports. UTWT 2021 episode satu. Ultra Trail World Tour 2021: Tarawera Ultra Marathon di Selandia Baru,  kemudian berlanjut untuk Ultra Trail Australia.","type":"vod","image_square":"","image_landscape":"https://op-picture.dens.tv/poster/files/lands/1677578045_land.jpg","image_potrait":"https://op-picture.dens.tv/poster/files/port/1 (52).jpg"},{"no":"3","id":"38","title":"ANIPLUS HD","slug":"aniplus-hd","description":"ANIPLUS menayangkan anime Jepang terbaik yang di targetkan untuk anak muda dan orang dewasa, dimana sebagian besar programnya didasarkan pada manga dan video game populer. (www.aniplus-asia.com)","type":"live_tv","image_square":"https://pic.dens.tv/tv_183x174/Aniplus_HD_1.jpg","image_landscape":"","image_potrait":"","category":"2"},{"no":"4","id":"42","title":"DensLife & Style","slug":"denslife-style","description":"DensLife & Style merupakan in-house Dens.TV yang menghadirkan konten yang menginspirasi mengenai kecantikan, fesyen, olahraga, desain dan interior.","type":"live_tv","image_square":"https://pic.dens.tv/tv_183x174/denstvshowtime.jpg","image_landscape":"","image_potrait":"","category":"1"},{"no":"5","id":"1811","title":"DRAWING GROUP STAGE M5 WORLD CHAMPIONSHIP","slug":"drawing-group-stage-m5-world-championship","description":"Hasil undian untuk babak grup M5 World Championship telah diumumkan","type":"article","image_square":"","image_landscape":"http://op-picture.dens.tv/wp/img/denslife_v1/1280x720/1699246215_denslife_v1.jpg","image_potrait":"","id_content_category":"247","title_content_category":"DPL-DensPlay"},{"no":"7","id":"98","title":"King of Karaoke PREMIERE Promo Video","slug":"king-of-karaoke-premiere-promo-video","description":"Content Rights: tvN.\\nSinopsis: Acara survival di mana para peserta menunjukkan kemampuan menyanyi mereka dan bersaing satu sama lain melalui karaoke untuk memenangkan hadiah utama sebesar 100 juta won.","type":"trailer","image_square":"","image_landscape":"https://picture.dens.tv/wp/img/upcoming_landscape_v1/1280x720/1700468893_upcoming_landscape_v1.jpg","image_potrait":"https://picture.dens.tv/wp/img/upcoming_potrait_v1/575x1028/King of Karaoke@3x.jpg"},{"no":"8","id":"26","title":"Tears of the Sun","slug":"tears-of-the-sun","description":"Seorang komandan operasi khusus, bersama pasukannya, berangkat untuk menyelamatkan Dr Lena dari hutan Nigeria. Namun, Dr Lena setuju untuk bergabung dengan mereka hanya jika mereka setuju untuk menyelamatkan 70 pengungsi lainnya juga.","type":"catchup_schedule","image_square":"","image_landscape":"https://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/tears of the sun_@3x.jpg","image_potrait":"https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1699954782_top_tvshowpotrait_v1.jpg"},{"no":"9","id":"22","title":"Findland Papa Episode 2","slug":"findland-papa-episode-2","description":"Yuri melihat poster dengan iklan pekerjaan mencari \\"anggota keluarga\\" untuk bekerja di sebuah kafe bernama Finland Papa. Bosan makan makanan yang dibeli di toko, dia pergi ke kafe dan diundang makan malam bersama staf.","type":"catchup_schedule","image_square":"","image_landscape":"https://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/finland papa_@3x.jpg","image_potrait":"https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1699954723_top_tvshowpotrait_v1.jpg"},{"no":"10","id":"1786","title":"Resep Camilan Halloween Sehat Gummy Pure Labu Manis","slug":"resep-camilan-halloween-sehat-gummy-pure-labu-manis","description":"Gummy pure labu bisa menjadi pilihan yang tepat untuk anak-anak yang suka makanan manis. Berbahan dasar labu yang tentunya memiliki banyak manfaat untuk kesehatan.","type":"article","image_square":"","image_landscape":"http://op-picture.dens.tv/wp/img/denslife_v1/1280x720/1698142937_denslife_v1.jpg","image_potrait":"","id_content_category":"246","title_content_category":"DLS-DensLife&Style"}]', 'N', '2023-11-08 11:23:23', '2023-11-23 08:13:21', '/top/section/inactivated_section'),
(12, 'test section tv', '2', 'N', '', '[{"no":"1","id":"42","title":"DensLife & Style","slug":"denslife-style","description":"DensLife &amp; Style merupakan in-house Dens.TV yang menghadirkan konten yang menginspirasi mengenai kecantikan, fesyen, olahraga, desain dan interior.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/denstvshowtime.jpg","image_landscape":"","image_potrait":"","category":"1"},{"no":"2","id":"126","title":"NaDooKorean","slug":"nadookorean","description":"NaDoo Korean menayangkan beragam serial drama Korea, tempat wisata, kuliner dan beragam program korea menarik lainnya.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1692762104_square.jpg","image_landscape":"","image_potrait":"","category":"1"},{"no":"3","id":"107","title":"DensPlay","slug":"densplay","description":"DensPlay merupakan in-house Dens.TV yang menghadirkan konten mengenai dunia eSports, gaming, dan live event.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1568359881_square.jpg","image_landscape":"","image_potrait":"","category":"1"}]', 'N', '2023-11-21 14:13:33', '2023-11-22 03:53:28', '/top/section/inactivated_section');
