(21, '11 Action Hits', '4', 'N', '', '[{"no":"1","id":"3219","title":"Season of the Witch | Rated : PG-13","slug":"season-of-the-witch-rated-pg-13","description":"Konten ini milik MovieWORLD. Tentara yang heroik dan rekan prajuritnya harus mengantarkan seorang wanita yang dituduh sebagai penyihir ke biara terpencil. Perjalanan yang sulit melintasi medan yang berbahaya menguji kekuatan dan keberanian mereka.\\n","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1597224647_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Season-of-the-Witch549x825.jpg"},{"no":"2","id":"2577","title":"The Monkey King 2 | Not Rated","slug":"the-monkey-king-2-not-rated","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Ketika seorang biksu terdampar di gurun, Raja Kera harus mengantarnya melintasi negeri itu untuk mengambil kitab suci dan melindunginya dari iblis jahat.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1559362726_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Monkey-King-2_549x825.jpg"},{"no":"3","id":"5865","title":"The Tower | Rated : Not Rated","slug":"the-tower-rated-not-rated","description":"Konten ini milik PT Cipta Mutu (My Cinema Asia). Pesta malam Natal di sebuah bangunan perumahan mewah berubah menjadi mengerikan ketika kebakaran terjadi.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1666153176_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Tower549x825.jpg"},{"no":"4","id":"2575","title":"Ip Man | Rated : R","slug":"ip-man-rated-r","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Kisah hidup Yip Man, orang pertama yang mengajarkan seni bela diri China Wing Chun dan pelatih Bruce Lee.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1559886497_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Ip-Man549x825.jpg"},{"no":"5","id":"5861","title":"Mojin : The Lost Legend | Rated : Not Rated","slug":"mojin-the-lost-legend-rated-not-rated","description":"Konten ini milik PT Cipta Mutu (My Cinema Asia). Pada tahun 1969, dua orang pria selamat dari makam supernatural. Mereka kemudian menjadi perampok makam. Dua puluh tahun kemudian di NYC, seseorang disewa untuk menemukan makam itu lagi.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1666151812_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Mojin-the-Lost-Legend549x825.jpg"},{"no":"6","id":"3211","title":"Free State of Jones | Rated : R","slug":"free-state-of-jones-rated-r","description":"Konten ini milik MovieWORLD. Menceritakan kisah petani yang menantang, Newt Knight, dan pemberontakan bersenjatanya yang luar biasa melawan Konfederasi.\\n","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1596783704_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Free-State-of-Jones549x825.jpg"},{"no":"7","id":"2151","title":"In the Name of the King : A Dungeon Siege Tale | Rated : PG-13","slug":"in-the-name-of-the-king-a-dungeon-siege-tale-rated-pg-13","description":"Konten ini milik MovieWORLD. Film petualangan fantasi Uwe Boll In the Name of the King: A Dungeon Siege Tale dibintangi oleh Jason Statham sebagai Petani.\\n","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/In-the-Name-of-the-King1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/in the king@3x.jpg"},{"no":"8","id":"6484","title":"New Kung Fu Cult Master 1 | Rated : PG-13","slug":"new-kung-fu-cult-master-1-rated-pg-13","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Putra Zhang Chui Shan dari Sekte Wu Dang, Zhang Wu Ji, menemukan dirinya secara tidak sengaja terlibat dalam pertarungan untuk Pedang Naga. Ketika dia tanpa sadar mempelajari keterampilan seni bela diri yang kuat dari kitab suci Jiuyin, Wu Ji melanjutkan untuk membantu enam sekte besar melawan pemerintahan yang korup.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1681274333_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/KungFu-Cult-Master1_549x825.jpg"},{"no":"9","id":"2627","title":"Dance to Death | Rated : PG-13","slug":"dance-to-death-rated-pg-13","description":"Konten ini milik CinemaWorld. Dance to Death (Russian: \\u0422\\u0430\\u043d\\u0446\\u044b \\u043d\\u0430\\u0441\\u043c\\u0435\\u0440\\u0442\\u044c) adalah sebuah film fiksi dari Rusia tahun 2017 yang disutradarai oleh Andrei Volgin. Dalam Hunger Games energi para remaja digunakan untuk kota mereka setelah kiamat nuklir. Dua anak muda dipaksa untuk bertarung untuk menentukan siapa yang harus dikorbankan. ","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1660034244_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Dance-to-Death549x825.jpg"},{"no":"10","id":"5859","title":"Man From No Where | Rated : R","slug":"man-from-no-where-rated-r","description":"Konten ini milik PT Cipta Mutu (My Cinema Asia). Seorang penjaga pegadaian yang pendiam dengan masa lalu yang kejam mengambil cincin perdagangan narkoba dan organ dengan harapan menyelamatkan anak yang merupakan satu-satunya temannya.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1666150981_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Man-from-Nowhere549x825.jpg"},{"no":"11","id":"2154","title":"Motorway | Rated : R","slug":"motorway-rated-r","description":"Konten ini milik MovieWORLD. Film aksi Hong Kong 2012 tentang seorang polisi yang menghadapi seorang pengemudi dalam final showdown.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1556597589_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Motorway.jpg"}]', 'N', '2024-01-22 13:48:24', '2024-02-01 06:26:53', '/top/section/inactivated_section');
