(25, '11 Most Favorite Recipes', '4', 'N', '', '[{"no":"1","id":"6152","title":"Taste Good Eps. 01 - Perfect Salmon For Christmas","slug":"taste-good-eps-01-perfect-salmon-for-christmas","description":"Pada Natal tahun ini, Chef Ayu rindu masakan-masakan yang pernah dibuat keluarganya. Salah satunya Nasi Salmon Nori dengan masakan yang lezat dan sederhana membuat iri adiknya sedang jauh di rumah.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1671703235_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Portrait-VOD-Per-episode_Taste-Good.jpg"},{"no":"2","id":"4882","title":"SECRET CHEF EPS. 01 - Teriyaki","slug":"secret-chef-eps-01-teriyaki","description":"Masakkan spesial untuk hari ulang tahun.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1643274888_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/POTRAIT-VOD-Teriyaki-rev.jpg"},{"no":"3","id":"5081","title":"Cooking Duck EPS. 1 - Bebek Goreng Lengkuas Honje","slug":"cooking-duck-eps-1-bebek-goreng-lengkuas-honje","description":"Resep serundeng lengkuas yang enak dengan memasak bersama honje \\/ kecombrang. Simak Bebek Goreng Lengkuas Honje ala Cooking Duck","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1648801745_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-Cover-Potrait-BEBEK-GORENG-LENGKUAS-HONJE.jpg"},{"no":"4","id":"6615","title":"Meat and Great : Worth To Wait (Part 1)","slug":"meat-and-great-worth-to-wait-part-1","description":"Dandy Darmono punya bengkel motor gede bersama sohibnya, Baso. Dandy sendiri juga mempunyai hobby masak daging. Dandy janjian sama teman-temannya untuk memperlihatkan motor yang sudah dikerjakan Baso, sekaligus memasak daging ribeye dan picanha untuk teman-temannya dan Baso. Namun ada kendala yang terjadi nih!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1683082147_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Portrait-VOD-Per-episode_Meat-and-Great.jpg"},{"no":"5","id":"4885","title":"SECRET CHEF EPS. 04 - Dakgangjeong","slug":"secret-chef-eps-04-dakgangjeong","description":"Bagi pecinta drakor sudah pasti mengenal ayam pedas manis khas Korea ini. Coba masak Dakgangjeong di rumah.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1643275638_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/POTRAIT-VOD-Dakganjeong.jpg"},{"no":"6","id":"5082","title":"Cooking Duck EPS. 2 - Tumis Pare Kulit Bebek Krispi ","slug":"cooking-duck-eps-2-tumis-pare-kulit-bebek-krispi","description":"Tips supaya sayur pare tidak pahit dan temukan cara memasak tumis pare kulit bebek krispi dan pedas bikin nagih!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1648803323_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/TUIS-PARE-KULIT-BEBEK-CRISPY-POTRAIT.jpg"},{"no":"7","id":"5084","title":"Cooking Duck EPS. 4 - Bebek Asap Ngohiong","slug":"cooking-duck-eps-4-bebek-asap-ngohiong","description":"Masakan oriental selain Peking Duck ada juga Bebek Asap Ngohiong. Yuk simak cara membuatnya!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1648804172_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/BEBEK-ASAP-NGOHIONG-POTRAIT.jpg"},{"no":"8","id":"4884","title":"SECRET CHEF EPS. 03 - Karaage","slug":"secret-chef-eps-03-karaage","description":"Masakkan mudah tapi selalu gagal buat ayam karaage super garing. Berikut tips cara membuat karaage!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1643275537_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/POTRAIT-VOD-Karaage.jpg"},{"no":"9","id":"6159","title":"Taste Good Eps. 03 - Rose Creamy Tteokbokki","slug":"taste-good-eps-03-rose-creamy-tteokbokki","description":"Pada suasana tahun baru, Chef Ayu teringat dengan makanan khas korea yaitu Tteokbokki, harumnya masakan Tteokbokki dari Chef Ayu membuat cita rasa pedas manis dan gurih yang tidak kalah originalnya seperti asli dari Korea.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1672386428_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Portrait-VOD-Per-episode_Taste-Good.jpg"},{"no":"10","id":"4883","title":"SECRET CHEF EPS. 02 - Chicken Nanban","slug":"secret-chef-eps-02-chicken-nanban","description":"Menambah keceriahan hari ini, yuk masak ayam goreng krispi yang dibalut dengan saus Nanban!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1643275303_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/POTRAIT-VOD-Chicken-Nanban.jpg"},{"no":"11","id":"4887","title":"SECRET CHEF EPS. 06 - Yakitori","slug":"secret-chef-eps-06-yakitori","description":"Kangen sama jalan-jalan di Jepang, apalagi dengan jajanan pinggir jalan yang sangat terkenal yaitu Yakitori.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1643275885_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/POTRAIT-VOD-Yakitori.jpg"}]', 'N', '2024-01-22 16:09:59', '2024-02-01 06:30:25', '/top/section/inactivated_section'),
(26, '11 Best Hidden Gem', '4', 'N', '', '[{"no":"1","id":"5881","title":"Pecah Rasa : Euforia di Gang Gloria Part 1","slug":"pecah-rasa-euforia-di-gang-gloria-part-1","description":"Bersama Rizky dengan motor kesayangannya akan berburu jajanan pinggir jalan di Gang Gloria, Glodok.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667287139_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-1-SEG-1.jpg"},{"no":"2","id":"5433","title":"Icip Skuy Eps. 01 - Pos Bloc Jakarta","slug":"icip-skuy-eps-01-pos-bloc-jakarta","description":"Kekocakan kakak beradik, Renaga Tahier dan Deirda Tahier saat mencoba cemilan unik dalam rantang dan minuman milik artis Prilly Latuconsina di \\u201cPicknick Yuk Nona Manis\\u201d.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1660116493_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Thumbnail-VOD-Icip-Skuy-Portrait-Rev.jpg"},{"no":"3","id":"6149","title":"Tentang Rasa Eps. 01 - Naked Bread","slug":"tentang-rasa-eps-01-naked-bread","description":"Konten ini milik DensTV Original Production. Kisah kesuksesan seorang ibu bercerita tentang rasa buatan rumah Panettone yang menjadi inspirasi untuk berbagi di Natal tahun ini.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1674619195_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Portrait-VOD-Tentang-Rasa.jpg"},{"no":"4","id":"5888","title":"Pecah Rasa : Euforia di Gang Gloria Part 3","slug":"pecah-rasa-euforia-di-gang-gloria-part-3","description":"Sebuah kedai kopi yang melegenda dengan menandai denyut kesibukan kawasan pecinaan Glodok pada awal abad ke-19 masih mengebul.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667287943_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-1-SEG-3.jpg"},{"no":"5","id":"5887","title":"Pecah Rasa : Euforia di Gang Gloria Part 2","slug":"pecah-rasa-euforia-di-gang-gloria-part-2","description":"Ada kuliner menarik di Gang Gloria, biasanya mie menggunakan sayuran sawi, di sini mie dipadukan dengan sayuran kangkung! Nonton cerita dibalik pembuatan mie tersebut!","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667287625_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-1-SEG-2.jpg"},{"no":"6","id":"6543","title":"Taste Of Middle East (Part 1)","slug":"taste-of-middle-east-part-1","description":"Astriza mengunjungi Masjid Agung Al Munada Darussalam Baiturrahman alias Masjid Perahu. Masjid yang terletak di Jalan Raya Casablanca, Jakarta Selatan ini, terinspirasi dari kisah Nabi Nuh.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1681785001_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01. Portrait-VOD-Per-episode_Halal-Kuliner.jpg"},{"no":"7","id":"5434","title":"Icip Skuy Eps. 02 - Wisata Kuliner di Ruang Kreatif Publik","slug":"icip-skuy-eps-02-wisata-kuliner-di-ruang-kreatif-publik","description":"Kekocakan kakak beradik, Renaga Tahier dan Deirda Tahier saat mencoba cemilan unik dalam rantang dan minuman milik artis Prilly Latuconsina di \\u201cPicknick Yuk Nona Manis\\u201d.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1657166097_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/02-Thumbnail-VOD-Icip-Skuy-Portrait.jpg"},{"no":"8","id":"5435","title":"Icip Skuy  Eps. 03 - Ceriakan Harimu Dengan Gelato","slug":"icip-skuy-eps-03-ceriakan-harimu-dengan-gelato","description":"Spot jajanan di ruang terbuka seperti di Pos Bloc saat cuaca panas adalah gelato. Kira-kira rasa gelato apa yang dipilih Renaga dan Deirda di Huma Ide Gelato Artisan?","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1657166100_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/03-Thumbnail-VOD-Icip-Skuy-Portrait.jpg"},{"no":"9","id":"5894","title":"Pecah Rasa : Ada yang Seru di Pasar Baru \\u2013 Part 3","slug":"pecah-rasa-ada-yang-seru-di-pasar-baru-part-3","description":"Biasanya dimasakin Rizky coba masak kerak telor sendiri. Berhasil gak nih?","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667291856_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-3-SEG-3.jpg"},{"no":"10","id":"6237","title":"Tentang Rasa Eps. 02 - Masakan 19","slug":"tentang-rasa-eps-02-masakan-19","description":"Menceritakan sebuah resto bernama Masakan 19 mempunyai konsep gang kecil dengan suasana rumahan yang menyajikan Chinese Food yang resepnya terjaga dari generasi terdahulu.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1674205733_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/02-Portrait-VOD-Tentang-Rasa.jpg"},{"no":"11","id":"7363","title":"Batu Escape Eps. 1 - Eksplorasi Rasa & Pesona","slug":"batu-escape-eps-1-eksplorasi-rasa-pesona","description":"Sinopsis: Dalam perjalanan escapenya, Abi mengunjungi beberapa tempat tempat kuliner terkenal di kota Batu, Malang, seperti Bakso Tulang Iga pak Widodo yang letaknya berdekatan dengan alun-alun kota Batu dan Warung nasi legendaris bernama Sego Empok Bu Wakini. Dalam perjalanannya tersebut Abi juga refreshing ke wisata keindahan alam Kaliwatu Rafting yang menantang adrenalinnya.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1695028908_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT (18).jpg"}]', 'N', '2024-01-22 16:16:05', '2024-02-01 06:30:17', '/top/section/inactivated_section'),
(27, '11 Sports Adventure', '4', 'N', '', '[{"no":"1","id":"4470","title":"Corsica Raid Aventure 2019 ","slug":"corsica-raid-aventure-2019","description":"Konten ini milik HorizonSports. Corsica Raid Aventure 2019, selama 5 hari 5 malam para pembalap melintasi Corsica tanpa henti. Corsica Raid Aventure adalah bagian dari ORWT (Outdoor Race World Tour) yang didirikan oleh para pembalap yang mengumpulkan balapan outdoor terbaik di 5 benua seperti International Raid Gasp\\u00e9sie di Kanada, Outdoor Race Costa Rica, Sin City di AS, dan Australian Expedition.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1698993821_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Corsica-Raid-Adventure-2019-(potrait).jpg"},{"no":"2","id":"6512","title":"GKA Freestyle World Cup - Salinas del Rey","slug":"gka-freestyle-world-cup-salinas-del-rey","description":"Konten ini milik HorizonSports. Salinas del Rey, Kolombia, adalah lokasi terbaru pada GKA Kite World Tour. Tempat ini mempunyai ombak dan air datar terbaik di pantai Karibia Kolombia.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1697707429_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/GKA-Freestyle-World-Cup---Salinas-del-Rey(potrait)-copy.jpg"},{"no":"3","id":"6122","title":"The Kalalau Trail in One Day","slug":"the-kalalau-trail-in-one-day","description":"Konten ini milik HorizonSports. Jalur ini melintasi 5 lembah subur, di atas tebing yang menjulang tinggi, sebelum berakhir di Pantai Kalalau.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1697771734_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/The-Kalalau-Trail-in-One-Day-(potrait)-copy.jpg"},{"no":"4","id":"5108","title":"Cape Epic 2022","slug":"cape-epic-2022","description":"Konten ini milik HorizonSports. Absa Cape Epic adalah balapan sepeda gunung dunia. Rutenya berubah setiap tahun, pengendara sepeda gunung amatir dan profesional dari seluruh dunia melewati 650 kilometer pemandangan alam yang belum terjamah dan pendakian setinggi 16.000 m.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1697707414_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/cape-epic-2022(potrait)-copy.jpg"},{"no":"5","id":"7074","title":"India Supercross 2022 Rd 5 Goa","slug":"india-supercross-2022-rd-5-goa","description":"Sinopsis: Liputan eksklusif dari Seri Indian Supercross 2022.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1692176527_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/India-Supercross-2022-Rd-5-Goa(potrait).jpg"},{"no":"6","id":"7068","title":"Moonraker Forest Rally 2023","slug":"moonraker-forest-rally-2023","description":"Content Rights: HorizonSports Limited.\\nSinopsis: Sorotan dari acara ikonik di Irlandia.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1692091807_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Moonraker-Forest-Rally-2023(potrait).jpg"},{"no":"7","id":"7067","title":"GT4 European Series 2023 Rd 2 Paul-Ricard - Race 2","slug":"gt4-european-series-2023-rd-2-paul-ricard-race-2","description":"Sinopsis: Liputan lengkap dari Seri GT4 Eropa 2023!","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1692092055_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/GT4-eps-2(potrait).jpg"},{"no":"8","id":"4997","title":"The Bay Games","slug":"the-bay-games","description":"Konten ini milik HorizonSports. Saatnya bagi para peserta untuk mengeluarkan potensi mereka dan menunjukkan kepada dunia apa yang mereka perjuangkan di pantai berpasir putih di Jervis Bay, NSW, Australia. ","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1698813094_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/the-bay-games-(potrait).jpg"},{"no":"9","id":"6509","title":"Lekkarod 2022 ","slug":"lekkarod-2022","description":"Konten ini milik HorizonSports. 30 tim dan 13 peserta dalam kategori ski-jo\\u00ebring mengikuti total 9 tahapan. Lekarod adalah acara yang diperhitungkan untuk Piala Dunia IFSS (Federasi Olahraga Kereta Luncur Internasional).","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1697773415_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/lekkarod-2022(potrait)-copy.jpg"},{"no":"10","id":"4465","title":"\\u00d6TILL\\u00d6 15 Years of Swimrun","slug":"\\u00d6till\\u00d6-15-years-of-swimrun","description":"Konten ini milik HorizonSports. 15 tahun yang lalu Mats Skott dan Michael Lemmel melihat kesempatan untuk membuat balapan epik. Siapa yang tahu bahwa \\u00d6TILL\\u00d6 akan menjadi awal dari olahraga renang baru?","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1699001254_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/otillo-15-years-of-swimrun(potrait) (1).jpg"},{"no":"11","id":"4970","title":"17th Olympus Marathon 2021","slug":"17th-olympus-marathon-2021","description":"Konten ini milik HorizonSports. Atlet dari seluruh dunia, memberikan upaya terbaik mereka, untuk menjalankan salah satu balapan paling spektakuler di dunia. Mendaki dari permukaan laut, ke puncak gunung tertinggi di Yunani. Gunung Olympus.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1699412435_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/17th-Olympus-Marathon-2021-(potrait) (1).jpg"}]', 'N', '2024-01-23 14:19:55', '2024-02-01 06:26:02', '/top/section/inactivated_section'),
(28, 'banner ads 3', '8', 'N', '3', '[{"no":"1","id":"3","title":"ads 3","type":"banner_ads","banner_url":"https:\\/\\/picture.dens.tv\\/wp\\/img\\/banner_v1\\/1765x220\\/1791790487_banner_v1.jpg","target":"_self","location":"https:\\/\\/www.drama-hits.id\\/","category_content":"external","content_id":"0","start_date":"2023-01-01 00:00:00","end_date":"2050-12-31 23:59:59"}]', 'Y', '2024-02-01 08:52:03', '2026-10-12 07:29:51', '/top/section/activated_section'),
(29, 'Dragon''s Year 2024!', '4', 'N', '', '[{"no":"1","id":"3305","title":"The White Storm 2 : Drug Lords | Rated : PG-13","slug":"the-white-storm-2-drug-lords-rated-pg-13","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Mantan anggota geng, Yu Shin-Tin, sedang dalam misi untuk menjatuhkan raja narkoba paling kuat di Hong Kong. ","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1652244198_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-White-Storm-2-Drug-Lords549x825.jpg"},{"no":"2","id":"5878","title":"Bleeding Steel | Rated: PG-13","slug":"bleeding-steel-rated-pg-13","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Jackie Chan berperan sebagai agen pasukan khusus yang berjuang untuk melindungi seorang wanita dari geng kriminal yang jahat.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1666325629_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Bleeding-Steel549x825.jpg"},{"no":"3","id":"6237","title":"Tentang Rasa Eps. 02 - Masakan 19","slug":"tentang-rasa-eps-02-masakan-19","description":"Menceritakan sebuah resto bernama Masakan 19 mempunyai konsep gang kecil dengan suasana rumahan yang menyajikan Chinese Food yang resepnya terjaga dari generasi terdahulu.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1674205733_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/02-Portrait-VOD-Tentang-Rasa.jpg"},{"no":"4","id":"5881","title":"Pecah Rasa : Euforia di Gang Gloria Part 1","slug":"pecah-rasa-euforia-di-gang-gloria-part-1","description":"Bersama Rizky dengan motor kesayangannya akan berburu jajanan pinggir jalan di Gang Gloria, Glodok.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667287139_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-1-SEG-1.jpg"},{"no":"5","id":"7531","title":"Mission Milano | Rated : PG-13","slug":"mission-milano-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Seorang pengusaha kaya (Huang Xiaoming) menyamar dengan seorang agen Interpol (Andy Lau) untuk melindungi penemuan baru, \\"Seed of God,\\" agar tidak jatuh ke tangan konglomerat kejahatan internasional.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1698302686_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/pot@3x (1).png"},{"no":"6","id":"6486","title":"Chasing the Dragon II: Wild Wild Bunch | Rated : PG-13","slug":"chasing-the-dragon-ii-wild-wild-bunch-rated-pg-13","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Serial penculik miliarder Logan telah merajalela di Hong Kong. Sekarang, gengnya membidik anak panah di luar Hong Kong, ke raja Makau yang makmur.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1681274640_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Chasing-The-Dragon-II-Wild-Wild-Bunch549x825.jpg"},{"no":"7","id":"7657","title":"The Silent War | Rated | PG-13","slug":"the-silent-war-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Setelah Perang Saudara Tiongkok, Biro 701 terus memantau transmisi terenskripsi antara pasukan pemberontak. Ketika frekuensi radio yang digunakan oleh lawan tiba-tiba menghilang, Agen Zhang meminta bantuan Ho, seorang penyetem piano tunanetra dengan pendengaran yang luar biasa, untuk membantu menemukan sinyal transmisi tersebut. Dapatkah Ho menemukan sinyal yang hilang dan menggagalkan kemungkinan rencana pembunuhan?","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/The-Silent-War1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/The-Silent-War549x825@3x.jpg"},{"no":"8","id":"2575","title":"Ip Man | Rated : R","slug":"ip-man-rated-r","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Kisah hidup Yip Man, orang pertama yang mengajarkan seni bela diri China Wing Chun dan pelatih Bruce Lee.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1559886497_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Ip-Man549x825.jpg"},{"no":"9","id":"2577","title":"The Monkey King 2 | Not Rated","slug":"the-monkey-king-2-not-rated","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Ketika seorang biksu terdampar di gurun, Raja Kera harus mengantarnya melintasi negeri itu untuk mengambil kitab suci dan melindunginya dari iblis jahat.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1559362726_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Monkey-King-2_549x825.jpg"},{"no":"10","id":"2576","title":"Lady of the Dynasty | Rated : R","slug":"lady-of-the-dynasty-rated-r","description":"Konten ini milik Celestial Tiger Entertainment (Celestial Movies). Sebuah hubungan cinta terkutuk terjadi antara permaisuri kekaisaran dinasti Tang dan Kaisar Xuanzong.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1559886495_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Lady-Of-Dynasty549x825 (1).jpg"},{"no":"11","id":"6889","title":"The Grandmaster | Rated : PG-13","slug":"the-grandmaster-rated-pg-13","description":"Disutradarai oleh pembuat film terkenal Wong Kar Wai, fitur aksi epik ini dimulai di Foshan ketika Ip Man, master seni bela diri dari selatan, menerima tantangan dari master utara Gong Yu Tian yang menua. Ip Man memenangkan pertarungan, tetapi kemudian dikalahkan oleh putri Gong Yu Tian, \\u200b\\u200bGong Er, yang dengannya Ip Man membentuk ikatan emosional\\u2026","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/The-Grandmaster1280x720@3x.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Grandmaster549x825@3x.jpg"}]', 'N', '2024-02-01 15:27:48', '2024-02-12 08:12:20', '/top/section/inactivated_section');
