(39, 'Cinta di  Penghujung Tahun', '4', 'N', '', '[{"no":"1","id":"8927","title":"Apakah Masih Sayang?","slug":"apakah-masih-sayang","description":"Sinopsis: \\"Bima terus berusaha memberi ingatan-ingatan baru pada Ayu.  Berusaha meyakinkan Ayu kalau\\nmereka adalah pasangan yang harmonis.  Bima terus memanjakan Ayu dengan jalan-jalan\\nmenikmati tempat-tempat mereka memiliki kenangan indah bersama.  Akhirnya, di suatu kejadian, Ayu berhasil membuka ruangan rahasia dan laci terkunci.  Ternyata di sana tersimpan rahasia yang berusaha dikubur dalam-dalam oleh suaminya tersebut. Mampukah hubungan mereka berdua diselamatkan?  Hanya mereka berdua yang mampu\\nmenjawabnya.\\"","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1732506347_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/04-Apakah Masih Sayang- pt04.jpg","trailer_url":""},{"no":"2","id":"8316","title":"Fall in Love at First Kiss | Rated : PG","slug":"fall-in-love-at-first-kiss-rated-pg","description":"Content Rights: PT Cipta Mutu (My Cinema Asia).\\nSinopsis: Diadaptasi dari serial manga Jepang \\"Itazura na Kiss\\", tentang seorang gadis remaja yang jatuh cinta dengan sesama seniornya sejak hari pertama mereka di sekolah menengah.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Fall-in-Love-at-First-Kiss1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Fall-in-Love-at-First-Kiss549x825@3x.jpg","trailer_url":""},{"no":"3","id":"5938","title":"Paris Je T''Aitme | Rated : R","slug":"paris-je-taitme-rated-r","description":"Konten ini milik PT Cipta Mutu Entertainment. Melalui lingkungan Paris, cinta terselubung, terungkap, ditiru, dihisap, diciptakan kembali, dan dibangkitkan.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667554168_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Paris-Je-Taime549x825 (1).jpg","trailer_url":""},{"no":"4","id":"8716","title":"Marrying Mr Perfect | Rated : PG-13","slug":"marrying-mr-perfect-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Winnie ditinggalkan oleh pacarnya di usia dua puluhan akhir dan tanpa sadar bertemu dengan Koo, seorang tycoon yang kejam dalam bisnis dan seorang playboy. Koo sementara menukar identitasnya dengan sopirnya demi alasan keamanan dan jatuh cinta pada Winnie karena dia adalah gadis pertama yang mencintainya apa adanya. Apa yang akan terjadi ketika Winnie mengetahui identitas asli Koo?","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Marrying-Mr-Perfect1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Marrying-Mr-Perfect549x825@3x.jpg","trailer_url":""},{"no":"5","id":"2164","title":"The Edge of Love | Rated : R","slug":"the-edge-of-love-rated-r","description":"Konten ini milik MovieWORLD. Kehidupan pria dari Wales yang karismatik Dylan Thomas dan hubungan cintanya dengan dua wanita.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1556786312_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Edge-of-Love.jpg","trailer_url":""},{"no":"6","id":"8889","title":"In the Mood for Love | Rated : PG-13","slug":"in-the-mood-for-love-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: \\u201cIn the Mood for Love\\u201d adalah karya Wong Kar-Wai yang paling diakui, menggambarkan hubungan cinta yang subtel antara Chow Mo Wan dan Su Li Zhen setelah keduanya mengetahui bahwa pasangan mereka berselingkuh. Tony Leung memenangkan Penghargaan Aktor Terbaik di Festival Film Cannes ke-53 atas peran utamanya dan menjadi artis Hong Kong pertama yang menerima penghargaan ini.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/In-the-Mood-for-Love1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/In-the-Mood-for-Love549x825@3x.jpg","trailer_url":""},{"no":"7","id":"8650","title":"Branding in Seongsu Eps.1","slug":"branding-in-seongsu-eps1","description":"Sinopsis: Berlatar di pusat branding, Seongsu-dong, sebuah fantasi romantis yang menceritakan kisah seorang kepala tim dan magang yang bertukar jiwa setelah sebuah ciuman tak sengaja.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/EP 1@3x (5).jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/EP 1@3x (4).jpg","trailer_url":""},{"no":"8","id":"3957","title":"Flying Blind | Rated : PG-13","slug":"flying-blind-rated-pg-13","description":"Konten ini milik My Cinema Europe. Kisah cinta dari seorang wanita yang lebih tua dan seorang pria muda, di dunia di mana keamanan adalah yang terpenting.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1624431962_land.png","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Flying-Blind.png","trailer_url":""},{"no":"9","id":"3923","title":"Westwind | Rated : PG-13","slug":"westwind-rated-pg-13","description":"Konten ini milik My Cinema Europe. Di perkemahan musim panas di Hongaria, saudara kembar bertemu pada tahun 1988.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1623984649_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Westwind.jpg","trailer_url":""}]', 'N', '2024-11-25 13:54:19', '2025-01-13 02:54:51', '/top/section/inactivated_section'),
(40, 'FAST Channel', '2', 'N', '', '[{"no":"1","id":"139","title":"wedotv movies (Free Trial)","slug":"wedotv-movies-free-trial","description":"Channel film aksi yang mendebarkan hingga drama emosional dan thriller penuh ketegangan.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/wedo-tv-movies183x174@3x.jpg","image_landscape":"","image_potrait":"","category":"13","trailer_url":""},{"no":"2","id":"142","title":"wedotv Amor (Free Trial)","slug":"wedotv-amor-free-trial","description":"Channel ini menampilkan Telenovela terpopuler dan program latin Amerika klasik terbaik sepanjang masa.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/wedo-tv-amor183x174@3x@3x.jpg","image_landscape":"","image_potrait":"","category":"13","trailer_url":""},{"no":"3","id":"140","title":"wedotv Big Stories (Free Trial)","slug":"wedotv-big-stories-free-trial","description":"Channel yang didedikasikan untuk hiburan faktual seperti sejarah alam, gaya hidup, profil tokoh, dan lain-lain.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/wedo-tv-big-stories183x174@3x.jpg","image_landscape":"","image_potrait":"","category":"13","trailer_url":""}]', 'N', '2024-12-03 13:47:43', '2024-12-19 09:49:41', '/top/section/inactivated_section'),
(41, 'Perayaan Akhir Tahun', '1', 'N', '', '[{"no":"1","id":"128","title":"Stingray Classica","slug":"stingray-classica","description":"Stingray Classica merupakan channel yang didedikasikan untuk musik klasik, konser, opera, balet, dan dokumenter.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1701423589_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"2","id":"130","title":"Dance TV","slug":"dance-tv","description":"Dance TV menghadirkan musik elektronik, masing-masing difokuskan pada genre tertentu sehingga selalu dapat mendengar suara yang sesuai dengan selera dan suasana hati saat ini.","type":"live_tv","image_square":"https:\\/\\/pic.dens.tv\\/tv_183x174\\/1701423510_square.jpg","image_landscape":"","image_potrait":"","category":"2","trailer_url":""},{"no":"3","id":"8987","title":"A Merry Friggin Christmas | Rated : PG","slug":"a-merry-friggin-christmas-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Family). \\nSinopsis: \\nBoyd Mitchler dan keluarganya harus menghabiskan Natal bersama keluarganya yang terasing dan penuh kekacauan. Setelah menyadari bahwa dia meninggalkan semua hadiah untuk putranya di rumah, dia memulai perjalanan bersama ayahnya untuk menempuh perjalanan pulang-pergi 8 jam sebelum matahari terbit.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/A-Merry-Friggin-Christmas1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/A-Merry-Friggin-Christmas549x825@3x.jpg","trailer_url":""},{"no":"4","id":"2231","title":"Le pere Noel (Santa Claus) | Not Rated","slug":"le-pere-noel-santa-claus-not-rated","description":"Konten ini milik Cipta Mutu Entertainment. Seorang anak laki-laki berusia 6 tahun yang menginginkan naik kereta luncur bersama Sinterklas.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1558076196_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/1561569891_port.jpg","trailer_url":""},{"no":"5","id":"8497","title":"Holiday Wishes | Rated : PG","slug":"holiday-wishes-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Family).\\nSinopsis: Danni Hartford, perencana pesta keluarga King, ingin menemukan saudara perempuannya. Britney, putri 15 tahun yang manja dari keluarga King, ingin memiliki kuda.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Holiday-Wishes1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Holiday-Wishes549x825@3x.jpg","trailer_url":""},{"no":"6","id":"6152","title":"Taste Good Eps. 01 - Perfect Salmon For Christmas","slug":"taste-good-eps-01-perfect-salmon-for-christmas","description":"Pada Natal tahun ini, Chef Ayu rindu masakan-masakan yang pernah dibuat keluarganya. Salah satunya Nasi Salmon Nori dengan masakan yang lezat dan sederhana membuat iri adiknya sedang jauh di rumah.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1671703235_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Portrait-VOD-Per-episode_Taste-Good.jpg","trailer_url":""},{"no":"7","id":"6049","title":"The Kitchen Musical Eps. 12","slug":"the-kitchen-musical-eps-12","description":"Saat Avilon bersiap untuk kebaktian Malam Natal yang sibuk, restoran baru Daniel, Silver Ray, membuat heboh dengan Hue Masters. Keretakan dalam hubungan Alex dan Maddie mulai terlihat saat dia mencoba mengundang Daniel ke pertemuan staf Natal.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1670489445_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Thumbnail-VOD-The-Kitchen-Musical-Portrait-Eps-12.jpg","trailer_url":""},{"no":"8","id":"2527","title":"Journey to the Christmas Star | Rated : G","slug":"journey-to-the-christmas-star-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Seorang gadis pemberani yang melakukan perjalanan berbahaya mencari Christmas Star untuk membebaskan kerajaan dari kutukan dan membawa kembali seorang putri yang telah lama hilang.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1639551693_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/journey-to-the-christmas-star549x825.jpg","trailer_url":""},{"no":"9","id":"6153","title":"Taste Good Eps. 02 - Holy Jolly Christmas Chicken","slug":"taste-good-eps-02-holy-jolly-christmas-chicken","description":"Selain Nasi Salmon Nori, Chef Ayu rindu dengan masakan Indian Butter Chicken. Seperti namanya Indian Butter Chicken yaitu masakan dengan ciri menggunakan rempah-rempah khas India dengan cita rasa aroma yang tajam.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1671703397_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/02-Portrait-VOD-Per-episode_Taste-Good.jpg","trailer_url":""},{"no":"10","id":"6343","title":"The Christmas Hot Dog | Rated : PG-13","slug":"the-christmas-hot-dog-rated-pg-13","description":"Konten ini milik Shorts TV. Ego bersatu dalam rencana untuk mengubah Natal menjadi Januari. Hanya ada satu masalah, Will telah menemukan seorang wanita yang membagikan hot dog gratis dan minatnya untuk menemukannya dapat menggagalkan motivasi dari seluruh acara spesial Natal.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1676875867_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/the-christmas-hotdog-(potrait).jpg","trailer_url":""}]', 'N', '2024-12-19 16:49:32', '2025-01-13 02:53:34', '/top/section/inactivated_section'),
(42, 'Liburan Penuh Petualangan', '4', 'N', '', '[{"no":"1","id":"8950","title":"The Snow Queen & the Princess | Rated : PG","slug":"the-snow-queen-the-princess-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Kidz).\\nSinopsis: Kai dan Gerda tinggal di sebuah kota kecil yang tenang, ketika tiba-tiba Roh Es datang untuk membekukan semua orang. Namun, Ila, seorang penyihir kecil, datang untuk membantu para pahlawan. Bersama-sama, mereka pergi ke dunia ajaib Mirrorland untuk mengembalikan Roh Es.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/The-Snow-Queen-and-the-Princess1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/The-Snow-Queen-and-the-Princess549x825@3x.jpg","trailer_url":""},{"no":"2","id":"8949","title":"Red Shoes and the 7th Dwarfs | Rated : PG","slug":"red-shoes-and-the-7th-dwarfs-rated-pg","description":"Content Rights: PT Cipta Mutu  Entertainment (My Kidz).\\nSinopsis: Para pangeran yang telah diubah menjadi kurcaci mencari sepatu merah milik seorang wanita untuk mematahkan kutukan, meskipun itu tidak akan mudah. Sebuah parodi dengan sentuhan yang tak terduga.\\n","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Red-Shoes-and-the-Seven-Dwarfs1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Red-Shoes-and-the-Seven-Dwarfs549x825@3x.jpg","trailer_url":""},{"no":"3","id":"8948","title":"Manou the Swift | Rated : Not Rated","slug":"manou-the-swift-rated-not-rated","description":"Content Rights: PT Cipta Mutu Entertainmen (My Kidz).\\nSinopsis: Manou, seekor burung kecil yang tumbuh dengan keyakinan bahwa dia adalah seekor camar, belajar terbang hanya untuk menemukan bahwa dia tidak akan pernah bisa. Ketika dia melarikan diri dari rumah, dia bertemu dengan burung-burung dari spesiesnya sendiri dan akhirnya mengetahui siapa dirinya sebenarnya.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Manou-the-Swift1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Manou-the-Swift549x825@3x.jpg","trailer_url":""},{"no":"4","id":"8947","title":"Here Comes the Grump | Rated : G","slug":"here-comes-the-grump-rated-g","description":"Content Rights: PT Cipta Mutu Entertainment (My Kidsz).\\nSinopsis: Kerajaan balon, naga polisi konyol, dan penyihir ceria adalah hal-hal yang persis seperti yang Terry ingat dari dongeng aneh Neneknya. Namun, yang membingungkan adalah bahwa semua itu nyata, dan kenyataannya tidak semenyenankan yang dia bayangkan.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Here-Comes-the-Grump1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Here-Comes-the-Grump549x825@3x.jpg","trailer_url":""},{"no":"5","id":"8489","title":"Mune Guardian of The Moon | Rated : PG","slug":"mune-guardian-of-the-moon-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Cinema).\\nSinopsis: Mune, seekor rusa muda, dipilih sebagai Penjaga Bulan baru. Bersama dengan Glim, seorang gadis yang terbuat dari lilin, dan Sohone, Penjaga Matahari baru, mereka harus mengembalikan matahari dari Necross yang jahat.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Mune-Guardian-of-the-Moon1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Mune-Guardian-of-the-Moon549x825@3x.jpg","trailer_url":""},{"no":"6","id":"1741","title":"Niko & the Way to the Stars | Rated : G","slug":"niko-the-way-to-the-stars-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Seekor rusa melakukan pencarian untuk menemukan dan menyelamatkan ayahnya, yang dia yakini sebagai anggota Pasukan Terbang Elit Sinterklas yang terkenal di dunia.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1637568398_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Niko-and-the-way-to-the-stars549x825.jpg","trailer_url":""},{"no":"7","id":"1649","title":"Magic Silver | Rated : PG","slug":"magic-silver-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Putri Bluerose harus menyelamatkan nyawa ayahnya, Raja Gnome Biru, dan mengambil kembali Magic Silver yang membawa cahaya matahari ke bumi.\\n","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1637570939_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/magic-silver549x825.jpg","trailer_url":""},{"no":"8","id":"3217","title":"Mr. Go | Rated : PG","slug":"mr-go-rated-pg","description":"Konten ini milik MovieWORLD. Kisah Ling-ling, seekor gorila tua, yang terkenal karena dia bermain baseball di Liga Baseball Korea.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1597050669_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/1598606907_port.jpg","trailer_url":""},{"no":"9","id":"2527","title":"Journey to the Christmas Star | Rated : G","slug":"journey-to-the-christmas-star-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Seorang gadis pemberani yang melakukan perjalanan berbahaya mencari Christmas Star untuk membebaskan kerajaan dari kutukan dan membawa kembali seorang putri yang telah lama hilang.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1639551693_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/journey-to-the-christmas-star549x825.jpg","trailer_url":""},{"no":"10","id":"8497","title":"Holiday Wishes | Rated : PG","slug":"holiday-wishes-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Family).\\nSinopsis: Danni Hartford, perencana pesta keluarga King, ingin menemukan saudara perempuannya. Britney, putri 15 tahun yang manja dari keluarga King, ingin memiliki kuda.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Holiday-Wishes1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Holiday-Wishes549x825@3x.jpg","trailer_url":""}]', 'N', '2024-12-19 17:13:34', '2025-01-13 02:53:42', '/top/section/inactivated_section'),
(43, 'Lezatnya Liburan', '4', 'N', '', '[{"no":"1","id":"7427","title":"Batu Escape Eps. 2 - Jelajah Selera & Seru di Malang","slug":"batu-escape-eps-2-jelajah-selera-seru-di-malang","description":"Sinopsis: Abi mengawali Escapenya ke tempat wisata air terjun Coban Putri, dimana pada tempat itu Abi menemukan ketenangan dengan mendengar suara gemercik air dari alam. Ditengah tengah perjalanannya Abi mencoba kuliner dengan rasa bintang lima harga kaki lima yaitu Arigo Steak House yang menyediakan berbagai macam menu daging. Abi juga mengunjungi tempat nyoklat favorit di kota Batu yaitu Es Coklat nyerocol yang menawarkan selera minum coklat sambil melihat keindahan gunung di kota Malang.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1696317586_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT (20).jpg","trailer_url":""},{"no":"2","id":"8928","title":"Bogor Escape : Good Trip, Good Food, Good Mood! {This is Bogor}","slug":"bogor-escape-good-trip-good-food-good-mood-this-is-bogor","description":"Sinopsis: Amel memulai harinya dengan semangat baru untuk menemukan kedamaian yang ia cari. Ia mengunjungi Nicole\\u2019s River Park, sebuah tempat wisata indah yang menawarkan berbagai spot menarik dengan keindahan di setiap sudutnya, memberikan Amel ruang untuk meresapi ketenangan yang selama ini ia butuhkan. Setelah puas mengeksplorasi, Amel melanjutkan petualangannya dengan mencicipi kuliner lokal. Ia berkunjung ke Sate Haji Kadir, warung sate legendaris yang terkenal dengan bumbu yang khas dan daging yang empuk dan lembut. Selain rasa yang menggoda, suasana hangat dan akrab di warung ini mengingatkan Amel untuk lebih menghargai hal-hal kecil dalam hidup.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1732596525_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/ld.jpg","trailer_url":""},{"no":"3","id":"6149","title":"Tentang Rasa Eps. 01 - Naked Bread","slug":"tentang-rasa-eps-01-naked-bread","description":"Konten ini milik DensTV Original Production. Kisah kesuksesan seorang ibu bercerita tentang rasa buatan rumah Panettone yang menjadi inspirasi untuk berbagi di Natal tahun ini.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1674619195_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/01-Portrait-VOD-Tentang-Rasa.jpg","trailer_url":""},{"no":"4","id":"6044","title":"The Kitchen Musical Eps. 7","slug":"the-kitchen-musical-eps-7","description":"Jeux Gastronomique Mondiale, organisasi kuliner bergengsi yang menempati peringkat lima puluh koki teratas di dunia, akan datang ke Avilon dan Alex memilih Maddie untuk menjadi sous chef terkemuka di menu eksperimentalnya. Keduanya bekerja sama dengan sangat baik sehingga semua orang, termasuk Selena, menyadarinya.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1670488081_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Thumbnail-VOD-The-Kitchen-Musical-Portrait-Eps-07 (1).jpg","trailer_url":""},{"no":"5","id":"7145","title":"Taste Good Eps. 19 - Mie Koclok Cirebon","slug":"taste-good-eps-19-mie-koclok-cirebon","description":"Sinopsis: Mie Koclok sebuah hidangan mie rebus yang berasal dari wilayah Cirebon, Jawa Barat, akan disiapkan Chef Ayu. Kuah kental dan gurih yang diguyur di atas mie sangat tepat disajikan saat cuaca hujan dan suasana dingin.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1692936893_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/19-Portrait-VOD-Per-episode_Taste-Good.jpg","trailer_url":""},{"no":"6","id":"6153","title":"Taste Good Eps. 02 - Holy Jolly Christmas Chicken","slug":"taste-good-eps-02-holy-jolly-christmas-chicken","description":"Selain Nasi Salmon Nori, Chef Ayu rindu dengan masakan Indian Butter Chicken. Seperti namanya Indian Butter Chicken yaitu masakan dengan ciri menggunakan rempah-rempah khas India dengan cita rasa aroma yang tajam.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1671703397_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/02-Portrait-VOD-Per-episode_Taste-Good.jpg","trailer_url":""},{"no":"7","id":"8129","title":"Sweet Yummy Eps. 1 : Amy and Cake (Part 2)","slug":"sweet-yummy-eps-1-amy-and-cake-part-2","description":"Sinopsis: Croissant dengan teh merupakan perpaduan yang pas banget. Kedua kombinasi ini bisa juga dinikmati untuk breakfast, lunch ataupun dinikmati sendiri sebagai cemilan seperti Dania. Gak lupa macarons dengan rasa matcha dan raspberry! Yuk cek makanan cantik apa saja ya yang di coba Dania di Amy dan Cake?","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1710318865_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/thumbnail_VOD-E1-P2-POTRAIT (1).jpg","trailer_url":""},{"no":"8","id":"8385","title":"Main Rasa Eps. 6 : Ending Of Exploration (Part 2)","slug":"main-rasa-eps-6-ending-of-exploration-part-2","description":"Sinopsis: Kalo ada Vania sudah tentu ada makan! Setelah berhasil melewati berbagai macam rintangan permainan, Vania mencoba makanan serta minuman yang penuh dengan rasa manis di Play Caf\\u00e9. Salah satu makanan yang dapat menghilang rasa Lelah Vania yaitu Chocolate Mocha Brownies dengan tekstur yang super lembut.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1716795506_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/VOD-E6-P2-POTRAIT (1).jpg","trailer_url":""},{"no":"9","id":"8491","title":"Foodsaurus : Koboi Lokal Pemakan Daging T-Rex!!","slug":"foodsaurus-koboi-lokal-pemakan-daging-t-rex","description":"Sinopsis: Melvin memang selalu berjodoh dengan makanan. Kali ini ia mendatangkan restoran bernama Django\\u2019s yang ia dapatkan akibat lari dari masalah, tetapi kesalahan itu malah membuat ia bisa menyantap makanan yang nikmat dan mewah. ","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1720428970_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/fd-pt.jpg","trailer_url":""},{"no":"10","id":"5897","title":"Pecah Rasa : Yang Dicari Dalam Rasa Hidden Gem Serpong \\u2013 Part 3","slug":"pecah-rasa-yang-dicari-dalam-rasa-hidden-gem-serpong-part-3","description":"Hacep banget! Asam pedas Pecak Gurame dan Udang Rebon yang merupakan masakan emak di Warung Pecak Duren.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667292931_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/VOD-POTRAIT_PECAH-RASA-EP-4-SEG-3.jpg","trailer_url":""}]', 'N', '2024-12-19 17:21:25', '2025-01-13 02:53:48', '/top/section/inactivated_section'),
(44, 'Seru Dengan Melodi', '4', 'N', '', '[{"no":"1","id":"6052","title":"The Kitchen Musical Boston Eps. 1","slug":"the-kitchen-musical-boston-eps-1","description":"Teman Gretchen dan Noah sangat membutuhkan investor untuk mempertahankan restoran mereka, The Boston, secara finansial. ","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1676270433_land.png","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Portrait-VOD-Thumbnail-The-Boston01_An-Artist_-Two-Partners-and-a-Soup.png","trailer_url":""},{"no":"2","id":"6040","title":"The Kitchen Musical Eps. 3","slug":"the-kitchen-musical-eps-3","description":"Seorang Produser Bollywood terkenal membeli Avilon - selama tiga hari - untuk pernikahan putrinya dengan seorang Prancis! Alex, Maddie, dan Daniel berjuang untuk membuat menu yang memadukan masakan Prancis dan India dengan sempurna.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1670482181_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Thumbnail-VOD-The-Kitchen-Musical-Portrait-Eps-03-rev.jpg","trailer_url":""},{"no":"3","id":"8850","title":"Office Hour : Rahasia Hati - Ferdy Element","slug":"office-hour-rahasia-hati-ferdy-element","description":"Sinopsis: Menjadi salah satu lagu yang sempat ditolak oleh teman-teman band Element, lagu Rahasia Hati berhasil populer dikalangan remaja tahun itu. Hingga di tahun 2021, lagu ini menjadi sumber inspirasi diciptakannya menu kopi Bencoolen Coffee yang merupakan bisnis milik dua vokalis dari band Element. ","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1730170880_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Thumbnail-VOD-Portrait-Office-Hour-Performance-Ferdy-Element-(Rahasia-Hati)-Portrait.jpg","trailer_url":""},{"no":"4","id":"8895","title":"Show Champion - Eps.17","slug":"show-champion-eps17","description":"Sinopsis: \\"Show Champion\\" menampilkan lagu-lagu hits paling populer di Korea dan rookie-super baru yang akan datang di dunia musik K-Pop.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/showchamp land@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/show champ pot@3x.jpg","trailer_url":""},{"no":"5","id":"5939","title":"Single By Contract | Rated : Not Rated","slug":"single-by-contract-rated-not-rated","description":"Konten ini milik PT Cipta Mutu Entertainment. Lila, seorang gadis yang kembali ke Berlin setelah berada di luar negeri selama setahun, bertemu Chris. Dia jatuh cinta padanya, tetapi apa yang dia tidak tahu adalah bahwa Chris adalah bintang rock terkenal dengan banyak penggemar mengejarnya, termasuk adik perempuannya.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667554490_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Single-Contract549x825.jpg","trailer_url":""},{"no":"6","id":"2813","title":"Love N'' Dancing | Rated : PG-13","slug":"love-n-dancing-rated-pg-13","description":"Konten ini milik Cipta Mutu Entertainment. Seorang guru bahasa Inggris (Amy Smart) dan mantan juara dansa (Tom Malloy) menjadi lebih dari sekadar teman dansa saat mereka bersaing untuk memperebutkan gelar juara dunia.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/love-n-dancing1280x720@3x.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/love-n-dancing549x825.jpg","trailer_url":""},{"no":"7","id":"2516","title":"I''m Not There | Rated : R","slug":"im-not-there-rated-r","description":"Konten ini milik Cipta Mutu Entertainment. Film biografi yang sangat ditunggu-tunggu tentang penyanyi dan penulis lagu legendaris Bob Dylan.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1558075755_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/1561552797_port.jpg","trailer_url":""},{"no":"8","id":"2236","title":"Bandslam | Rated : PG","slug":"bandslam-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment. Ceritanya berkisar pada Will dan Charlotte, yang membentuk ikatan melalui kecintaan mereka pada musik. ","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1558067616_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/bandslam549x825.jpg","trailer_url":""},{"no":"9","id":"2169","title":"Boychoir | Rated : PG-13","slug":"boychoir-rated-pg-13","description":"Konten ini milik MovieWORLD. Seorang remaja (Garrett Wareing) dengan bakat luar biasa ditantang oleh seorang guru vokal (Dustin Hoffman).","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1556269238_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/Boychoir.jpg","trailer_url":""},{"no":"10","id":"2168","title":"The Last Five Years | Rated : PG-13","slug":"the-last-five-years-rated-pg-13","description":"Konten ini milik MovieWORLD. Menceritakan kisah romansa antara Jamie Wellerstein (Yordania) dan Cathy Hiatt (Kendrick). Ceritanya mundur ke awal masa pacaran mereka.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1556786401_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/The-Last-Five-Years.jpg","trailer_url":""}]', 'N', '2024-12-19 17:26:45', '2025-01-13 02:53:58', '/top/section/inactivated_section');
INSERT INTO `section` (`id`, `title`, `type`, `show_number`, `sort`, `json_content`, `visible`, `create_date`, `update_date`, `ctrloc`) VALUES
(45, 'Keceriaan di Akhir Tahun', '4', 'N', '', '[{"no":"1","id":"8940","title":"100% Warga Konoha : TOXSHIP Atau TOXSH1T?","slug":"100-warga-konoha-toxship-atau-toxsh1t","description":"Sinopsis: Siapa yang pernah terjebak dalam toxic relationship? Ternyata hubungan yang toxic bukan hanya hubungan sama pacar aja loh guys, tapi juga bisa hubungan dengan teman dekat sampe teman kantor. Tapi dari semua ketoxican yang ada, tetap loh guys yang jadi imbasnya adalah kalangan MILENIAL dan GEN Z, kaya Ranggi yang katanya engga kuat Kerjasama dengan Daffa si anak Gen Z yang banyak gaya!","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1733285267_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/pt (28).jpg","trailer_url":""},{"no":"2","id":"8961","title":"See You Tomorrow | Rated : PG-13","slug":"see-you-tomorrow-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Di dunia yang penuh kekacauan ini, setiap kota memiliki \\"navigator\\" mereka sendiri yang dapat membantu menyelesaikan berbagai masalah hubungan. Pemilik bar, Chen, dan rekannya, Guan, adalah navigator legendaris. Namun, saat membantu seorang gadis bernama Xiao Yu, mereka juga harus menghadapi masalah mereka sendiri dalam sebuah perjalanan epik menuju penemuan diri yang membawa kehidupan mereka dari puncak kejayaan hingga ke titik terendah.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/See-You-Tomorrow1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/See-You-Tomorrow549x825@3x.jpg","trailer_url":""},{"no":"3","id":"8886","title":"Shrink | Rated: R","slug":"shrink-rated-r","description":"Content Rights: Cipta Mutu Entertainment (My Cinema)\\nSynopsis: Tidak mampu menghadapi tragedi pribadi baru-baru ini, seorang terapis selebriti terkenal di LA berubah menjadi pecandu ganja, tidak peduli dengan penampilannya, dan mulai merasa bahwa dirinya tidak mampu membantu pasien-pasiennya.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/shrink1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/shrink549x825@3x.jpg","trailer_url":""},{"no":"4","id":"8267","title":"Asterix And Obelix God Save Britannia | Rated : PG","slug":"asterix-and-obelix-god-save-britannia-rated-pg","description":"Content Rights: PT Cipta Mutu (My Family).\\nSinopsis: Asterix menyeberangi Selat Inggris untuk membantu sepupu kedua, Anticlimax, menghadapi Julius Caesar dan pasukan Romawi yang menyerang.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Asterix-and-Obelix-God-Save-Britannia1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Asterix-and-Obelix-God-Save-Britannia549x825@3x.jpg","trailer_url":""},{"no":"5","id":"8498","title":"It''s Kind of A Funny Story | Rated : PG","slug":"its-kind-of-a-funny-story-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Family).\\nSinopsis: Seorang remaja yang menderita depresi klinis mendapatkan awal baru setelah ia mendaftar diri ke ruang perawatan psikiatri dewasa.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Its-Kind-of-a-Funny-Story1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Its-Kind-of-a-Funny-Story549x825@3x.jpg","trailer_url":""},{"no":"6","id":"8715","title":"Over My Dead Body | Rated : PG-13","slug":"over-my-dead-body-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Komedii gelap ini dimulai dengan kemunculan mayat yang tidak dikenal di depan pintu sebuah apartemen. Takut bahwa mayat tersebut akan mengubah apartemen mereka menjadi \\"apartemen berhantu,\\" yang dapat menyebabkan penurunan drastis nilai properti, empat keluarga yang tinggal di lantai yang sama berusaha memindahkan mayat itu, terjerat dalam kekacauan.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/Over-My-Dead-Body1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Over-My-Dead-Body549x825@3x.jpg","trailer_url":""},{"no":"7","id":"8888","title":"One and Only | Rated : PG-13","slug":"one-and-only-rated-pg-13","description":"Content Rights: Celestial Movies.\\nSinopsis: Veteran penari jalanan Ding Lei mengundang penari jalanan yang penuh semangat, Chen Shuo, untuk bergabung dengan klub tari miliknya. Ketegangan terjadi saat Chen menari bersama penari terbaik di klub tersebut. Chen mengejar impian untuk tampil di atas panggung, namun ia menemukan bahwa Ding mengundangnya untuk alasan lain. Saat keduanya menghadapi masa-masa sulit, dapatkah mereka mengubah arah tantangan yang mereka hadapi?","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/One-and-Only1280x720@3x.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/One-and-Only549x825@3x.jpg","trailer_url":""},{"no":"8","id":"2250","title":"Bad Moms | Rated : R","slug":"bad-moms-rated-r","description":"Konten ini milik Cipta Mutu Entertainment. Bercerita tentang tiga ibu yang terlalu banyak bekerja, tetapi kurang dihargai.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1558067613_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/1561566506_port.jpg","trailer_url":""},{"no":"9","id":"2063","title":"One for the Money | Rated : PG-13","slug":"one-for-the-money-rated-pg-13","description":"Konten ini milik Cipta Mutu Entertainment (My Cinema). Stephanie Plum yang menganggur dan baru saja bercerai mendapatkan pekerjaan di sebuah bisnis sepupunya, di mana tugas pertamanya menempatkan dia pada jejak seorang polisi lokal dari masa lalunya yang romantis.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1632303163_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/one_for_the_money549x825.jpg","trailer_url":""},{"no":"10","id":"5930","title":"A Few Best Men | Rated : Not Rated","slug":"a-few-best-men-rated-not-rated","description":"Konten ini milik PT Cipta Mutu Entertianment (My Family). Seorang pengantin pria dan tiga teman baiknya melakukan perjalanan ke pedalaman Australia untuk pernikahan.","type":"vod","image_square":"","image_landscape":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/lands\\/1667553671_land.jpg","image_potrait":"https:\\/\\/op-picture.dens.tv\\/poster\\/files\\/port\\/A-Few-Best-Men549x825.jpg","trailer_url":""}]', 'N', '2024-12-19 17:30:43', '2025-01-13 02:54:05', '/top/section/inactivated_section'),
(46, 'Liburan Penuh Teror', '4', 'N', '', '[{"no":"1","id":"8983","title":"Podcastis Season 3 : Saya Menginjak Rambut Kuntilanak Ketika Shift Malam","slug":"podcastis-season-3-saya-menginjak-rambut-kuntilanak-ketika-shift-malam","description":"Sinopsis: Kali ini Rachel dan Anna mengundang narasumber bernama Kancil dimana ia menceritakan kisahnya saat mendapatkan shift malam untuk bekerja di kantor yang ia tempati. Ketika menjalankan bagiannya untuk penjagaan malam, Kancil banyak diganggu oleh sosok tak kasat mata salah satunya yang paling menyeramkan yaitu sosok \\u201cWanita Berkebaya\\u201d. Bagaimanakah kisah lengkap Kancil Ketika menjalankan tugasnya dengan suasana yang selalu mencengkam? Saksikan selengkapnya hanya di Podcastis (Podcast Kisah Mistis).","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1734501214_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/pt (19).jpg","trailer_url":""},{"no":"2","id":"8856","title":"Gerbang Dimensi S3 : Gerbang tak kasat mata di Gedung Biru, Bekasi","slug":"gerbang-dimensi-s3-gerbang-tak-kasat-mata-di-gedung-biru-bekasi","description":"Sinopsis: Anna seorang praktisi supranatural dan juga Galuh seorang spirit illustrator melakukan penelusuran ke salah satu tempat terbengkalai. Anna melakukan penerawang terhadap \\u201csosok\\u201d yang ada di sana selama masa hidupnya sedangkan Galuh mencoba untuk menggambarkan sosok tersebut sesuai dengan kemampuannya. Selain itu, mereka juga mengulik sejarah untuk mengetahui awal mula terjadinya tempat tersebut bisa terbengkalai.","type":"vod","image_square":"","image_landscape":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/lands\\/1730260262_land.jpg","image_potrait":"http:\\/\\/pic.dens.tv\\/poster\\/files\\/port\\/Portrait-VOD-Per-episode_Gerbang-Dimensi-S3.jpg","trailer_url":""},{"no":"3","id":"8770","title":"Monstrous | Rated : PG-13","slug":"monstrous-rated-pg-13","description":"Content Rights: ROCK Action.\\